"""Replay-metric fixtures: synthetic 'mocap + RPM' flight generated by the reference model."""

import math

import numpy as np
import pytest

import aerial_model as am
import aerial_replay as rp
from aerial_profiles import load_vehicle


def _synthetic_flight(seconds=4.0, dt=1 / 360, mocap_noise=0.0, seed=0):
    v = load_vehicle("x500_px4_gz", with_battery=False)
    rng = np.random.default_rng(seed)
    w_h = am.hover_rotor_speed(v)
    s = am.initial_state(v, p=(0, 0, 2), rotor_speed=w_h)
    t, p, q, w = [], [], [], []
    for k in range(int(seconds / dt)):
        tk = k * dt
        # collective chirp plus a small differential (roll/pitch) excitation
        base = w_h * (1 + 0.05 * math.sin(2 * math.pi * (0.5 + 0.5 * tk) * tk))
        diff = 3.0 * math.sin(2 * math.pi * 1.3 * tk)
        cmd = np.array([base + diff, base + diff, base - diff, base - diff])
        t.append(tk)
        p.append(s.p.copy())
        q.append(s.q.copy())
        w.append(s.rotor_speed.copy())
        s = am.step(v, s, cmd, dt)
    p = np.array(p) + rng.normal(0, mocap_noise, (len(p), 3))
    return v, np.array(t), p, np.array(q), np.array(w)


def test_replay_recovers_thrust_coefficient_from_clean_mocap():
    v, t, p, q, w = _synthetic_flight()
    rep = rp.thrust_replay_report(t, p, q, w, v.rotors[0].kf, v.mass, half_window=6)
    assert rep["kf_scale_fit"] == pytest.approx(1.0, abs=0.01)
    assert rep["samples"] > 1000


def test_replay_detects_miscalibrated_thrust_coefficient():
    v, t, p, q, w = _synthetic_flight(mocap_noise=2e-4, seed=1)
    rep = rp.thrust_replay_report(t, p, q, w, 0.8 * v.rotors[0].kf, v.mass, half_window=12)
    assert rep["kf_scale_fit"] == pytest.approx(1.25, abs=0.03)


def test_rotor_drag_shows_up_as_lateral_specific_force():
    v, t, p, q, w = _synthetic_flight()
    rep = rp.thrust_replay_report(t, p, q, w, v.rotors[0].kf, v.mass, half_window=6)
    assert rep["lateral_specific_force_rms"] > 0.0
    assert rep["lateral_specific_force_rms"] < 0.5


def test_rpm_conversion():
    assert rp.rpm_to_rad_s([60.0])[0] == pytest.approx(2 * math.pi)
